mapper.select:
SELECT *
FROM attendance_record
WHERE tenant_id = #{tenantId}

    AND store_id IN
    #{sid}

AND check_date BETWEEN #{startDate} AND #{endDate}
AND deleted = 0
ORDER BY check_date, employee_id

SELECT ar.*, pe.employee_name, pe.position, ps.store_name FROM attendance_record ar LEFT JOIN pos_employee pe ON ar.employee_id = pe.id LEFT JOIN pos_store ps ON ar.store_id = ps.id WHERE ar.deleted = 0 AND ar.tenant_id = #{tenantId}
AND ar.store_id IN #{sid}
AND (#{employeeId} IS NULL OR ar.employee_id = #{employeeId}) AND (#{startDate} IS NULL OR ar.check_date >= #{startDate}) AND (#{endDate} IS NULL OR ar.check_date <= #{endDate}) ORDER BY ar.check_date DESC, ar.employee_id

SELECT ar.id, ar.tenant_id, ar.employee_id, ar.check_date, ar.check_in_time, ar.check_out_time, ar.check_in_method, ar.check_out_method, ar.check_in_location, ar.check_out_location, ar.check_in_status, ar.check_out_status, ar.is_late, ar.late_minutes, ar.is_early_leave, ar.early_leave_minutes, ar.is_absence, ar.work_minutes, ar.remark, ar.config_id, ar.store_id, ar.create_time, ar.update_time, ar.deleted, pe.employee_name, pe.position, ps.store_name FROM attendance_record ar LEFT JOIN pos_employee pe ON ar.employee_id = pe.id AND pe.deleted = 0 LEFT JOIN pos_store ps ON ar.store_id = ps.id AND ps.deleted = 0 WHERE ar.deleted = 0 AND ar.tenant_id = #{tenantId}
AND ar.store_id IN #{sid}
AND ar.employee_id = #{employeeId}
AND ar.check_date >= #{startDate}
AND ar.check_date <= #{endDate}
ORDER BY ar.check_date DESC, ar.employee_id ASC, ar.id DESC
